-- Coditu — the MEINEvim component registry.
--
-- GENERATED by scripts/sync-evim-components.mjs from the delivery repository.
-- Do not edit by hand: re-run the script instead.
--
--   node scripts/sync-evim-components.mjs           rewrite this file
--   node scripts/sync-evim-components.mjs --check   fail if it is stale
--
-- ## Why this is a separate seed file
--
-- `supabase/seed.sql` is generated from the team's Notion export and says so at
-- the top. This list does not come from Notion: it is read out of the delivery
-- repository — one row per SPFx solution's `preconfiguredEntries[0]` (the title
-- and toolbox icon EVIM sees in SharePoint), one per feature in the React app's
-- own registry. `supabase/config.toml` lists both files, in order, under
-- `[db.seed]`.
--
-- ## Why it is not a migration
--
-- A migration runs BEFORE the seed on `supabase db reset`, so the project row it
-- needs does not exist yet locally and the insert would be a silent no-op on
-- every fresh checkout. Against the hosted database, where the project has
-- existed since the import, this file is safe to run exactly as it is: one
-- idempotent statement that opens no transaction (the Supabase SQL editor
-- discards those).
--
-- ## What it will not do
--
-- `on conflict do nothing`, so it only ever ADDS. A component renamed in the
-- delivery repo, or given a different toolbox icon, is not overwritten here —
-- renaming is a decision with a paper trail (the item history follows the row),
-- and this file is not the place to make it silently. The script prints those
-- as drift; act on them in the app.

insert into public.components (project_id, name, slug, kind, icon)
select project.id, listed.name, listed.slug, listed.kind::component_kind, listed.icon
from public.projects project
cross join (values
  ('Copier'                     , 'copier'                     , 'spfx' , null),
  ('EVIM Akkordeon'             , 'evim-akkordeon'             , 'spfx' , 'Page'),
  ('EVIM Anniversaries'         , 'evim-anniversaries'         , 'spfx' , 'Page'),
  ('EVIM Banner'                , 'evim-banner'                , 'spfx' , 'Page'),
  ('EVIM Banner and News'       , 'evim-banner-and-news'       , 'spfx' , 'News'),
  ('EVIM Banner Half Image'     , 'evim-banner-half-image'     , 'spfx' , 'Page'),
  ('EVIM Button Link'           , 'evim-button-link'           , 'spfx' , 'Page'),
  ('EVIM Calendar'              , 'evim-calendar'              , 'spfx' , 'Calendar'),
  ('EVIM Carousel with Links'   , 'evim-carousel-with-links'   , 'spfx' , 'Page'),
  ('EVIM Dokumentenbibliothek'  , 'evim-dokumentenbibliothek'  , 'spfx' , 'SearchAndApps'),
  ('EVIM Embed Plus'            , 'evim-embed-plus'            , 'spfx' , 'Embed'),
  ('EVIM Heading & Separator'   , 'evim-heading-and-separator' , 'spfx' , 'TextBox'),
  ('EVIM Instagram Feed'        , 'evim-instagram-feed'        , 'spfx' , 'RecruitmentManagement'),
  ('EVIM Interactive Video'     , 'evim-interactive-video'     , 'spfx' , 'Page'),
  ('EVIM KPI and Metrics'       , 'evim-kpi-and-metrics'       , 'spfx' , 'AreaChart'),
  ('EVIM Link Buttons'          , 'evim-link-buttons'          , 'spfx' , 'Page'),
  ('EVIM Link Kachel'           , 'evim-link-kachel'           , 'spfx' , 'Tiles'),
  ('EVIM LinkedIn Feed'         , 'evim-linkedin-feed'         , 'spfx' , 'RecruitmentManagement'),
  ('EVIM Links Carousel'        , 'evim-links-carousel'        , 'spfx' , 'Page'),
  ('EVIM Lists'                 , 'evim-lists'                 , 'spfx' , 'Table'),
  ('EVIM Locale Editor'         , 'evim-locale-editor'         , 'spfx' , 'LocaleLanguage'),
  ('EVIM Main Navigation'       , 'evim-main-navigation'       , 'spfx' , 'Page'),
  ('EVIM News'                  , 'evim-news'                  , 'spfx' , 'News'),
  ('EVIM News Center'           , 'evim-news-center'           , 'spfx' , 'News'),
  ('EVIM Org Chart'             , 'evim-org-chart'             , 'spfx' , 'OrganizationChart'),
  ('EVIM People Directory'      , 'evim-people-directory'      , 'spfx' , 'People'),
  ('EVIM Poll'                  , 'evim-poll'                  , 'spfx' , 'Page'),
  ('EVIM Process & Timeline'    , 'evim-process-and-timeline'  , 'spfx' , 'TimelineProgress'),
  ('EVIM Rollover Contact Cards', 'evim-rollover-contact-cards', 'spfx' , 'ContactCard'),
  ('EVIM Search Banner'         , 'evim-search-banner'         , 'spfx' , 'Search'),
  ('EVIM Social Corner'         , 'evim-social-corner'         , 'spfx' , 'People'),
  ('EVIM Tabs'                  , 'evim-tabs'                  , 'spfx' , 'BulletedList2'),
  ('EVIM Themen Kachel'         , 'evim-themen-kachel'         , 'spfx' , 'GridViewMedium'),
  ('EVIM User Feedback'         , 'evim-user-feedback'         , 'spfx' , 'Feedback'),
  ('EVIM Video Carousel'        , 'evim-video-carousel'        , 'spfx' , 'Page'),
  ('Promo Alert'                , 'promo-alert'                , 'spfx' , null),
  ('Urgent Alert'               , 'urgent-alert'               , 'spfx' , null),
  ('EVIM React Library'         , 'evim-react-library'         , 'react', null),
  ('News-Redaktion'             , 'news-redaktion'             , 'react', null),
  ('Anfrage'                    , 'anfrage'                    , 'react', null),
  ('Redakteurkalender'          , 'redakteurkalender'          , 'react', null)
) as listed (name, slug, kind, icon)
where project.slug = 'meinevim'
on conflict (project_id, slug) do nothing;
